// Same pattern as ensureAbilitiesSubFile, for the Features and Actions
// companion files - needed by Level Up so it can append newly-gained
// features/actions there even if the Features/Actions tabs haven't been
// opened yet in this session (mirrors FeaturesTracker.ensureSubFile /
// ActionsTracker.ensureSubFile, which stay as-is for their own tabs).
async function ensureFeaturesSubFile(app, mainFile) {
  return ensureCharacterFile(app, mainFile, "Features", "---\ncssclasses:\n  - dnd-sheet\nlimited_uses: []\n---\n");
}

async function ensureActionsSubFile(app, mainFile) {
  return ensureCharacterFile(app, mainFile, "Actions", "---\ncssclasses:\n  - dnd-sheet\nactions_list: []\n---\n");
}

// Collects every named feature a character of this class/subclass would
// have picked up by the given level (levels 1..maxLevel inclusive) -
// same CLASS_LEVEL_FEATURES lookup and generic-placeholder-to-real-subclass-
// feature resolution (via SUBCLASS_LEVEL_FEATURES/SUBCLASS_FEATURE_DESC) that
// openLevelUpModal uses one level at a time, just walked across a whole
// range at once. Used by "Create Character sheet" to pre-fill every feature
// up through the starting level for a character who isn't starting at 1.
// A homebrew subclass (see getHomebrewSubclassLevelFeatures) is checked
// whenever the built-in table has nothing for this exact class+subclass
// name, giving it the same treatment as a built-in one - including at a
// level the built-in class table has no generic "gain a subclass feature"
// placeholder for at all (e.g. a homebrew feature at a level this class
// doesn't normally grant one), which the loop below can't reach on its
// own since it only ever walks levels perLevel already knows about.
function collectFeaturesUpToLevel(className, subclassName, maxLevel) {
  const perLevel = CLASS_LEVEL_FEATURES[className] || {};
  const builtInSubclassLevels = (SUBCLASS_LEVEL_FEATURES[className] && SUBCLASS_LEVEL_FEATURES[className][subclassName]) || null;
  const homebrewSubclassLevels = getHomebrewSubclassLevelFeatures(className, subclassName);
  const subclassLevels = builtInSubclassLevels || homebrewSubclassLevels;
  const result = [];
  const levels = Object.keys(perLevel)
    .map(Number)
    .filter((lvl) => lvl <= maxLevel)
    .sort((a, b) => a - b);
  // Only tracks levels where a real subclass-feature swap actually
  // happened (not every level perLevel has anything at all) - a level
  // where this class just grants something unrelated (e.g. Extra Attack)
  // still needs to be eligible for the homebrew fallback below.
  const subclassHandledLevels = new Set();
  for (const lvl of levels) {
    for (const feat of perLevel[lvl]) {
      const subFeats = feat.description === SUBCLASS_FEATURE_DESC ? subclassLevels[lvl] : null;
      if (subFeats && subFeats.length) {
        for (const sf of subFeats) result.push({ name: sf.name, description: sf.description });
        subclassHandledLevels.add(lvl);
      } else {
        result.push({ name: feat.name, description: feat.description });
      }
    }
  }
  if (!builtInSubclassLevels) {
    for (const lvlStr of Object.keys(homebrewSubclassLevels)) {
      const lvl = Number(lvlStr);
      if (lvl > maxLevel || subclassHandledLevels.has(lvl)) continue;
      for (const sf of homebrewSubclassLevels[lvl]) result.push({ name: sf.name, description: sf.description });
    }
  }
  return result;
}

// Same pattern as ensureFeaturesSubFile/ensureActionsSubFile above - needed
// by the "Create Character sheet" wizard's Spells and Gear pages, which run
// as plugin-level code (not a mounted tracker), so they can't reach a
// tracker instance's own ensureSubFile() method.
async function ensureSpellsSubFile(app, mainFile) {
  return ensureCharacterFile(
    app,
    mainFile,
    "Spells",
    "---\ncssclasses:\n  - dnd-sheet\nspells: []\nspell_slots_used: {}\nspellcasting_modifier: \"\"\nspell_attack_bonus: \"\"\nspell_save_dc: \"\"\n---\n"
  );
}
async function ensureInventorySubFile(app, mainFile) {
  return ensureCharacterFile(app, mainFile, "Inventory", "---\ncssclasses:\n  - dnd-sheet\ninventory_list: []\n---\n");
}

// ===================================================================
// D&D Beyond character importer - pure data helpers.
//
// Pastes a public D&D Beyond character URL/ID (Settings tab), fetches its
// data straight from D&D Beyond's own unofficial character API, and builds
// a brand-new character sheet in THIS plugin's own schema (main file +
// data_id + the 8 companion files) - see Dnd2024CharacterSheetPlugin's
// importFromDndBeyond() below for the orchestration.
//
// Every formula here (stat resolution, HP, AC, proficiency detection) is
// ported from the actual working source of the community "DnD Beyond
// Importer" Obsidian plugin (github.com/webcreator3478/D-D-Beyond-
// Character-Importer---Obsidian-Plugin, cloned and read directly - its own
// markdown-table output isn't used at all, only its field-path knowledge
// of D&D Beyond's undocumented JSON) rather than guessed from scratch,
// since that's a real, actively-used importer and this API has no public
// docs of its own.
//
// The character must be set to Public on D&D Beyond - same requirement as
// that reference plugin, since a public sheet's JSON needs no auth.
// ===================================================================

function extractDdbCharacterId(input) {
  const str = String(input || "").trim();
  const match = str.match(/\/characters\/(\d+)/);
  if (match) return match[1];
  if (/^\d+$/.test(str)) return str;
  return null;
}

async function fetchDdbCharacterData(id) {
  const resp = await requestUrl({
    url: `https://character-service.dndbeyond.com/character/v5/character/${id}`,
    headers: { Accept: "application/json" },
  });
  const char = resp.json && resp.json.data;
  if (!char) throw new Error("Unexpected response from D&D Beyond - is the character set to Public?");
  return char;
}

function ddbGetAllModifiers(char) {
  const m = char.modifiers || {};
  return [...(m.class || []), ...(m.race || []), ...(m.background || []), ...(m.feat || []), ...(m.item || [])];
}

function ddbStatValue(stats, overrides, bonuses, id) {
  const found = (stats || []).find((s) => s.id === id);
  const base = found ? found.value : 10;
  const overrideEntry = (overrides || []).find((s) => s.id === id);
  const override = overrideEntry ? overrideEntry.value : null;
  if (override != null) return override;
  const bonus = (bonuses || []).filter((b) => b.id === id).reduce((sum, b) => sum + (b.value || 0), 0);
  return (base != null ? base : 10) + bonus;
}

const DDB_STAT_SUBTYPE_TO_ID = {
  "strength-score": 1,
  "dexterity-score": 2,
  "constitution-score": 3,
  "intelligence-score": 4,
  "wisdom-score": 5,
  "charisma-score": 6,
};

// bonusStats from the raw API is typically all-null - real ability-score
// bonuses (feats, ASIs baked into modifiers, etc.) live in modifiers[*]
// instead, same discovery the reference plugin's own computeRawStats made.
function ddbComputeRawStats(char) {
  const allMods = ddbGetAllModifiers(char);
  const modifierStatBonuses = allMods
    .filter((m) => m.type === "bonus" && m.subType in DDB_STAT_SUBTYPE_TO_ID && m.value != null)
    .map((m) => ({ id: DDB_STAT_SUBTYPE_TO_ID[m.subType], value: m.value }));
  const bonuses = [...(char.bonusStats || []).filter((s) => s.value != null), ...modifierStatBonuses];
  const ids = { str: 1, dex: 2, con: 3, int: 4, wis: 5, cha: 6 };
  const out = {};
  for (const key of Object.keys(ids)) {
    out[key] = ddbStatValue(char.stats || [], char.overrideStats || [], bonuses, ids[key]);
  }
  return out;
}

function ddbCalcLevel(char) {
  return (char.classes || []).reduce((sum, c) => sum + (c.level || 0), 0);
}

function ddbCalcHP(char, conScore, totalLevel, allMods) {
  const base = char.baseHitPoints || 0;
  const bonus = char.bonusHitPoints || 0;
  const override = char.overrideHitPoints;
  const removed = char.removedHitPoints || 0;
  const temp = char.temporaryHitPoints || 0;
  const conMod = abilityModFromScore(conScore);
  const hpPerLevel = allMods
    .filter((m) => m.type === "bonus" && m.subType === "hit-points-per-level" && m.value != null)
    .reduce((sum, m) => sum + m.value, 0);
  const flatHp = allMods
    .filter((m) => m.type === "bonus" && m.subType === "hit-points" && m.value != null)
    .reduce((sum, m) => sum + m.value, 0);
  const max = override != null ? override : base + bonus + conMod * totalLevel + hpPerLevel * totalLevel + flatHp;
  return { max, current: max - removed, temp };
}

function ddbCalcAC(char, dexScore, statsById, allMods) {
  const dexMod = abilityModFromScore(dexScore);
  const conMod = abilityModFromScore(statsById[3] != null ? statsById[3] : 10);
  const wisMod = abilityModFromScore(statsById[5] != null ? statsById[5] : 10);
  let best = 10 + dexMod;
  let shieldBonus = 0;
  let wearingArmor = false;
  for (const item of char.inventory || []) {
    const def = item.definition;
    if (!def || !item.equipped || !def.armorClass) continue;
    if (def.armorTypeId === 4) {
      shieldBonus = Math.max(shieldBonus, def.armorClass);
      continue;
    }
    wearingArmor = true;
    const addDex = def.armorTypeId !== 3;
    const maxDex = def.armorTypeId === 2 ? 2 : 999;
    const ac = def.armorClass + (addDex ? Math.min(dexMod, maxDex) : 0);
    if (ac > best) best = ac;
  }
  if (!wearingArmor) {
    for (const m of allMods) {
      if (m.subType === "unarmored-defense-constitution") best = Math.max(best, 10 + dexMod + conMod);
      if (m.subType === "unarmored-defense-wisdom") best = Math.max(best, 10 + dexMod + wisMod);
    }
  }
  for (const m of allMods) {
    if (m.type === "bonus" && m.subType === "armor-class" && m.value != null) best += m.value;
  }
  return best + shieldBonus;
}

const DDB_ALIGNMENTS = {
  1: "Lawful Good",
  2: "Neutral Good",
  3: "Chaotic Good",
  4: "Lawful Neutral",
  5: "True Neutral",
  6: "Chaotic Neutral",
  7: "Lawful Evil",
  8: "Neutral Evil",
  9: "Chaotic Evil",
};

function ddbStripHtml(html) {
  return String(html || "")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n\n")
    .replace(/<\/li>/gi, "\n")
    .replace(/<li>/gi, "- ")
    .replace(/<[^>]+>/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&nbsp;/g, " ")
    .replace(/&quot;/g, '"')
    .trim();
}

