// Every #Spell note in the vault, same lookup SpellsTracker.getSpellPages()
// uses (kept as a free function here since the creation wizard runs at the
// plugin level, not from a mounted tracker instance).
function getAllSpellNotes(app) {
  const files = app.vault.getMarkdownFiles();
  const results = [];
  for (const f of files) {
    if (isTemplateNote(app, f)) continue;
    const cache = app.metadataCache.getFileCache(f);
    if (!cache) continue;
    const tags = getAllTags(cache) || [];
    if (tags.includes("#Spell")) results.push({ file: f, fm: cache.frontmatter || {} });
  }
  return results;
}

