// True if `className` can actually learn a cantrip named `spellName`, per
// CANTRIP_CLASS_LIST above. A name with no entry there is allowed for
// everyone - an unrecognized/unmapped cantrip should stay pickable rather
// than silently vanish from every class's list.
function cantripAllowedForClass(spellName, className) {
  const allowed = CANTRIP_CLASS_LIST[spellName];
  if (!allowed || !allowed.length) return true;
  return allowed.includes(className);
}

// Same idea as CANTRIP_CLASS_LIST above, but for LEVELED spells (1st-9th) -
